		noWaitButton.getAccessibleContext().setAccessibleName("No Wait");
		noWaitButton.addActionListener(new _Anon_ActionListener_2());
		addButton(noWaitButton);
	}

	public void showDialog()
    {
		answered = false;
		if (!isShowing()) {
			DockingWindowManager.showDialog(null, this);
		}

		if (answered && actionID == DO_NOT_WAIT) {
			throw new StopWaitingException();
		}
	}

	public bool isAnsweredNo() {
		return answered && actionID == DO_NOT_WAIT;
	}

