		msgText.setMaximumSize(msgText.getPreferredSize());
		msgPanel.add(msgText, BorderLayout.CENTER);

		innerPanel.add(msgPanel, BorderLayout.CENTER);
		innerPanel.getAccessibleContext().setAccessibleName("Ghidra Go Wait");
		return innerPanel;
	}

